  using var host=new Form{ShowInTaskbar=false,Size=new(500,500)};host.Show();using var menu=new ConfigurationMenu();int invoked=0;foreach(var glyph in new[]{"\uE72D","\uE70F","\uE74D","\uE9D9","\uE768"})menu.AddAction(glyph,()=>invoked++);
  foreach(var dark in new[]{true,false}){Design.Dark=dark;menu.Prepare("Germany · VLESS",false,new[]{"Connect","Share","Edit","Delete","Ping"},new[]{true,true,true,true,true});menu.Show(host,new Point(30,30));Pump(50);assert(menu.Opacity>0&&menu.Opacity<1,"configuration menu opens gradually");Pump(200);assert(menu.Region!=null&&!menu.Region.IsVisible(0,0),"configuration menu rounded geometry");using(var bitmap=new Bitmap(menu.Width,menu.Height)){menu.DrawToBitmap(bitmap,menu.ClientRectangle);bitmap.Save(Path.Combine(AppContext.BaseDirectory,dark?"review-config-menu-dark.png":"review-config-menu-light.png"));}menu.Close();assert(menu.Visible,"configuration menu closes gradually");Pump(220);assert(!menu.Visible,"configuration menu close finishes");}
  Design.Dark=true;menu.Prepare("کانفیگ",true,new[]{"اتصال","اشتراک‌گذاری","ویرایش","حذف","پینگ"},new[]{true,true,true,true,true});menu.Show(host,new Point(30,30));Pump(200);var card=((ToolStripControlHost)menu.Items[0]).Control;card.Controls.OfType<Button>().First().PerformClick();assert(invoked==0,"action waits for closing animation");Pump(230);assert(invoked==1&&!menu.Visible,"menu action runs once after closing");host.Close();
 }
 static void CheckTrafficRefresh(Client client,Action<bool,string> assert){
  using var process=System.Diagnostics.Process.GetCurrentProcess();client.preferences.Language="en";client.ApplyLanguage();client.xray=process;client.activeProfileKey=client.ProfileKey(client.Profiles[0]);
  try{client.SetControls();int titleChanges=0,hintChanges=0,speedChanges=0;client.stateTitle.TextChanged+=(_,_)=>titleChanges++;client.stateHint.TextChanged+=(_,_)=>hintChanges++;var label=client.metrics["download"][0];client.Metric("download","1 KB/s");label.TextChanged+=(_,_)=>speedChanges++;
   for(int i=0;i<40;i++){client.SyncUi();client.Metric("download","1 KB/s");}
   assert(titleChanges==0&&hintChanges==0&&speedChanges==0,"unchanged traffic ticks do not rewrite status or speed labels");
   for(int i=2;i<=41;i++){client.SyncUi();client.Metric("download",i+" KB/s");client.Metric("usage",i+" KB");}
   assert(speedChanges==40&&titleChanges==0&&hintChanges==0,"changing traffic only updates metric values");assert(label is StableLabel&&label.Parent is BufferedTable,"traffic values use buffered fixed geometry");
  }finally{client.xray=null;client.activeProfileKey=null;client.SetControls();}
 }
