  var edited=(System.Text.Json.Nodes.JsonObject)link[0].DeepClone();Outbound(edited)!["streamSettings"]!["wsSettings"]!["path"]="/edited path";var exported=Parse(ShareText(edited))[0];assert(Outbound(exported)!["streamSettings"]?["wsSettings"]?["path"]?.ToString()=="/edited path"&&Outbound(exported)?["settings"]?["vnext"]?[0]?["users"]?[0]?["id"]?.ToString()=="021f5c70-2ad6-4f88-b3f0-2f4f0e0a9bc1","edited QR URI retains credentials and transport");
  var trojan="trojan://p%40ss%23word@node.example:443?type=grpc&serviceName=test&authority=cdn.example&security=tls&sni=cdn.example&alpn=h2#Trojan";assert(ShareText(Parse(trojan)[0])==trojan,"Trojan sharing preserves encoded password and all parameters");
